-- Baseline: the production schema as of 2026-11-18, before Flyway took over.
-- Production is baselined at version 1 (baseline-on-migrate), so this file only runs on an empty
-- database (a new install or a local rehearsal copy). Do not edit it: add V2__..., V3__... instead.
-- herds_age_backup (a one-off backup table, not mapped by any entity) is left out on purpose.

-- Tables are in alphabetical order, so some foreign keys point at tables created further down.
SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE `amcs_collections` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `amcs_updated_at` datetime(6) DEFAULT NULL,
  `amcs_updated_by` varchar(64) DEFAULT NULL,
  `amount` double NOT NULL,
  `animal_type` varchar(32) DEFAULT NULL,
  `clr` double DEFAULT NULL,
  `collection_date` date NOT NULL,
  `fat` double DEFAULT NULL,
  `imported_at` datetime(6) DEFAULT NULL,
  `member_code` varchar(32) NOT NULL,
  `quality_manual` bit(1) DEFAULT NULL,
  `quantity` double NOT NULL,
  `quantity_manual` bit(1) DEFAULT NULL,
  `rate_per_litre` double DEFAULT NULL,
  `sample_no` int NOT NULL,
  `shift` varchar(16) NOT NULL,
  `snf` double DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_amcs_member_date_shift_sample` (`member_code`,`collection_date`,`shift`,`sample_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `animal_onboarding_steps` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `detail` varchar(1000) DEFAULT NULL,
  `done_date` date DEFAULT NULL,
  `end_date` date NOT NULL,
  `event_id` bigint DEFAULT NULL,
  `feed_share_pct` int DEFAULT NULL,
  `notes` varchar(500) DEFAULT NULL,
  `sort_order` int DEFAULT NULL,
  `start_date` date NOT NULL,
  `status` varchar(20) NOT NULL,
  `step_key` varchar(40) NOT NULL,
  `title` varchar(255) NOT NULL,
  `onboarding_id` bigint NOT NULL,
  `choices` varchar(500) DEFAULT NULL,
  `problems` varchar(300) DEFAULT NULL,
  `step_no` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `FK5tnkeoexpkwuqax7f25hyp4ol` (`onboarding_id`),
  CONSTRAINT `FK5tnkeoexpkwuqax7f25hyp4ol` FOREIGN KEY (`onboarding_id`) REFERENCES `animal_onboardings` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `animal_onboardings` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `arrival_date` date NOT NULL,
  `completed_date` date DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `herd_id` bigint NOT NULL,
  `notes` varchar(1000) DEFAULT NULL,
  `quarantine_days` int NOT NULL,
  `start_event_id` bigint DEFAULT NULL,
  `status` varchar(20) NOT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `animal_requirements` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `animal_stage` varchar(255) NOT NULL,
  `body_weight_max` double DEFAULT NULL,
  `body_weight_min` double DEFAULT NULL,
  `breed` varchar(255) DEFAULT NULL,
  `calcium_req` double DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `crude_protein_req` double DEFAULT NULL,
  `dry_matter_intake` double DEFAULT NULL,
  `fiber_req` double DEFAULT NULL,
  `magnesium_req` double DEFAULT NULL,
  `me_req` double DEFAULT NULL,
  `milk_yield_max` double DEFAULT NULL,
  `milk_yield_min` double DEFAULT NULL,
  `mineral_req` double DEFAULT NULL,
  `phosphorus_req` double DEFAULT NULL,
  `remarks` text,
  `tdn_req` double DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `water_req` double DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `apartments` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `address` varchar(255) DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UKd8d8ytdbtd18cda4ok23dc2uh` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `assets` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `category` varchar(255) DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `location` varchar(255) DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `purchase_date` date DEFAULT NULL,
  `serial_number` varchar(255) DEFAULT NULL,
  `status` varchar(255) DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `value` double DEFAULT NULL,
  `market_value` double DEFAULT NULL,
  `market_value_manual` bit(1) DEFAULT NULL,
  `market_value_note` varchar(300) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `audit_package_attachments` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `content` longblob NOT NULL,
  `content_type` varchar(100) DEFAULT NULL,
  `file_name` varchar(200) DEFAULT NULL,
  `included` tinyint(1) NOT NULL DEFAULT '1',
  `package_id` bigint NOT NULL,
  `size_bytes` int DEFAULT NULL,
  `uploaded_at` datetime(6) DEFAULT NULL,
  `uploaded_by` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_audit_att_pkg` (`package_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `audit_package_expenses` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `amount` double NOT NULL,
  `category` varchar(100) DEFAULT NULL,
  `expense_date` date NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `excluded` tinyint(1) NOT NULL DEFAULT '0',
  `ledger_expense_id` bigint DEFAULT NULL,
  `package_id` bigint NOT NULL,
  `paid_by` varchar(100) DEFAULT NULL,
  `segment` varchar(10) DEFAULT NULL,
  `edited` tinyint(1) NOT NULL DEFAULT '0',
  `reviewed` tinyint(1) NOT NULL DEFAULT '0',
  `reviewed_by` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_audit_exp_pkg` (`package_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `audit_packages` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) DEFAULT NULL,
  `created_by` varchar(100) DEFAULT NULL,
  `document` longblob,
  `document_saved_at` datetime(6) DEFAULT NULL,
  `document_saved_by` varchar(100) DEFAULT NULL,
  `gst_note` varchar(1000) DEFAULT NULL,
  `include_gst` tinyint(1) NOT NULL DEFAULT '0',
  `notes` varchar(2000) DEFAULT NULL,
  `period_from` date NOT NULL,
  `period_to` date NOT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `updated_by` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UKgm8936bs1tinmt03oiftqnhm5` (`period_from`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `bank_month_notes` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `month` varchar(7) NOT NULL,
  `note` varchar(1000) NOT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `updated_by` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK18kacg4uakdcdhuac2jq7kwoe` (`month`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `bank_rules` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `category` varchar(100) DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `created_by` varchar(100) DEFAULT NULL,
  `direction` varchar(6) NOT NULL,
  `hits` int NOT NULL,
  `kind` varchar(10) NOT NULL,
  `last_used` datetime(6) DEFAULT NULL,
  `pattern` varchar(120) NOT NULL,
  `segment` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `bank_statement_files` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `account_last4` varchar(4) DEFAULT NULL,
  `content` longblob NOT NULL,
  `file_name` varchar(200) DEFAULT NULL,
  `pages` int DEFAULT NULL,
  `period_from` date NOT NULL,
  `period_to` date NOT NULL,
  `size_bytes` int DEFAULT NULL,
  `uploaded_at` datetime(6) DEFAULT NULL,
  `uploaded_by` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `bank_transactions` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `account_last4` varchar(4) DEFAULT NULL,
  `amount` double NOT NULL,
  `balance` double DEFAULT NULL,
  `bank_ref` varchar(100) DEFAULT NULL,
  `category` varchar(100) DEFAULT NULL,
  `counterparty` varchar(120) DEFAULT NULL,
  `dedupe_key` varchar(191) NOT NULL,
  `direction` varchar(6) NOT NULL,
  `fetched_at` datetime(6) DEFAULT NULL,
  `kind` varchar(10) DEFAULT NULL,
  `ledger_id` bigint DEFAULT NULL,
  `match_reason` varchar(160) DEFAULT NULL,
  `mode` varchar(10) DEFAULT NULL,
  `narration` varchar(500) DEFAULT NULL,
  `note` varchar(255) DEFAULT NULL,
  `posted` tinyint(1) NOT NULL DEFAULT '0',
  `rule_id` bigint DEFAULT NULL,
  `segment` varchar(10) DEFAULT NULL,
  `status` varchar(10) NOT NULL,
  `txn_date` date NOT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `updated_by` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK3c4ummggqfdyl15cdsgp6ebq4` (`dedupe_key`),
  KEY `idx_bank_txn_date` (`txn_date`),
  KEY `idx_bank_txn_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `breed_masters` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `avg_max` double DEFAULT NULL,
  `below_avg_max` double DEFAULT NULL,
  `description` varchar(255) DEFAULT NULL,
  `formula_type` varchar(255) DEFAULT NULL,
  `length_ratio` double DEFAULT NULL,
  `low_max` double DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `slightly_overweight_max` double DEFAULT NULL,
  `very_low_max` double DEFAULT NULL,
  `base_price` double DEFAULT NULL,
  `normal_yield` double DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UKb5tjkg5d6v3yhmteqn59xudqu` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `categories` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) DEFAULT NULL,
  `icon_code` varchar(255) DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `type` enum('EXPENSE','INCOME') NOT NULL,
  `created_by` varchar(255) DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `updated_by` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cat_type` (`type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `customer_subscriptions` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `billing_cycle` enum('HALF_YEARLY','MONTHLY','QUARTERLY','YEARLY') NOT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `customer_id` bigint NOT NULL,
  `delivery_address` text,
  `next_renewal` date DEFAULT NULL,
  `pause_from` date DEFAULT NULL,
  `pause_to` date DEFAULT NULL,
  `plan_id` bigint NOT NULL,
  `start_date` date NOT NULL,
  `status` enum('ACTIVE','CANCELLED','EXPIRED','PAUSED') NOT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cs_status` (`status`),
  KEY `idx_cs_customer` (`customer_id`),
  KEY `idx_cs_cust_status` (`customer_id`,`status`),
  KEY `idx_cs_plan` (`plan_id`),
  KEY `idx_cs_renewal` (`next_renewal`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `customers` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `address` varchar(255) DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `phone` varchar(255) NOT NULL,
  `default_rate` double DEFAULT '45',
  PRIMARY KEY (`id`),
  KEY `idx_cust_phone` (`phone`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `emergency_contacts` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `phone` varchar(20) NOT NULL,
  `role` varchar(60) DEFAULT NULL,
  `sort_order` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `expense_attachments` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `content` longblob NOT NULL,
  `content_type` varchar(100) DEFAULT NULL,
  `expense_id` bigint NOT NULL,
  `file_name` varchar(200) DEFAULT NULL,
  `size_bytes` int DEFAULT NULL,
  `uploaded_at` datetime(6) DEFAULT NULL,
  `uploaded_by` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_expense_att_expense` (`expense_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `expenses` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `amount` double NOT NULL,
  `category` varchar(255) NOT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `date` date NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `created_by` varchar(255) DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `updated_by` varchar(255) DEFAULT NULL,
  `herd_id` bigint DEFAULT NULL,
  `paid_by` varchar(255) DEFAULT NULL,
  `settled` tinyint(1) NOT NULL DEFAULT '0',
  `settled_at` datetime(6) DEFAULT NULL,
  `settled_by` varchar(255) DEFAULT NULL,
  `segment` varchar(10) DEFAULT NULL,
  `unaccounted` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_expense_date` (`date`),
  KEY `idx_exp_date` (`date`),
  KEY `idx_exp_category` (`category`),
  KEY `idx_exp_herd_id` (`herd_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `farm_activities` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `category` enum('BIOSECURITY','HERD_CHECK','HYGIENE','MAINTENANCE') NOT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `day_of_week` varchar(255) DEFAULT NULL,
  `default_assigned_staff_id` bigint DEFAULT NULL,
  `description` text,
  `frequency` varchar(20) NOT NULL,
  `interval_days` int DEFAULT NULL,
