  `title` varchar(255) NOT NULL,
  `action_route` varchar(255) DEFAULT NULL,
  `anchor_date` date DEFAULT NULL,
  `days_of_month` varchar(255) DEFAULT NULL,
  `due_time` time(6) DEFAULT NULL,
  `reminder_enabled` bit(1) DEFAULT NULL,
  `reminder_end_time` time(6) DEFAULT NULL,
  `reminder_interval_hours` int DEFAULT NULL,
  `reminder_max_per_day` int DEFAULT NULL,
  `reminder_start_time` time(6) DEFAULT NULL,
  `system_key` varchar(255) DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `chain_id` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK1snr6kju8wx5soglq9f4bqiae` (`system_key`),
  KEY `idx_farm_activities_is_active` (`is_active`),
  KEY `idx_fa_is_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `farm_activity_logs` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `activity_id` bigint NOT NULL,
  `completed_by_staff_id` bigint DEFAULT NULL,
  `completed_date` date DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `due_date` date NOT NULL,
