  `completed_at` datetime(6) DEFAULT NULL,
  `due_time` time(6) DEFAULT NULL,
  `last_reminder_at` datetime(6) DEFAULT NULL,
  `reminder_count` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_fal_activity_due` (`activity_id`,`due_date`),
  KEY `idx_farm_activity_logs_due_date` (`due_date`),
  KEY `idx_farm_activity_logs_activity_id_due_date` (`activity_id`,`due_date`),
  KEY `idx_fal_due_date` (`due_date`),
  KEY `idx_fal_activity_due` (`activity_id`,`due_date`),
  KEY `idx_fal_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `feed_knowledge` (
